+        position.set("equilibriumTemp", buf.readUnsignedByte() - 40);
+        for (int i = 1; i <= 7; i++) {
+            int temperature = buf.readUnsignedByte() - 40;
+            if (i <= temperatureCount) {
+                position.set("batteryTemp" + i, temperature);
+            }
+        }
